sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.main-container{
	display: flex;
  min-height: 500px;
  padding: 0px 32px;
  justify-content: center;
  align-items: flex-end;
  gap: 32px;
  align-self: stretch;
  background-color: #04245c;
  //background: url(x_779492_softwar_0.banner_option_1.png) lightgray 50% / cover no-repeat;
}

.container-content{
	display: flex;
  max-width: 1246px;
  padding: 75px 0px 32px 0px;
  align-items: center;
  gap: 32px;
  flex: 1 0 0;
  align-self: stretch;
}

.container-content-titles{
	display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  flex: 1 0 0;
}

.text-title{
  color: #ffffff;

  /* Titles/Display */
  font-family: "Arial";
  font-size: 48px;
  font-style: normal;
  font-weight: 700;
  line-height: 125%; /* 60px */
}

.text-subtitle{
	color: #ffffff;
  /* Paragraphs/Regular */
  font-family: "Arial";
  font-size: 16px;
  font-style: normal;
  font-weight: 400;
  line-height: 160%; /* 25.6px */
}

.container-buttons{
	display: flex;
  align-items: flex-start;
  align-content: flex-start;
  gap: 16px;
  align-self: stretch;
  flex-wrap: wrap;
}

.button-secondary, .button-primary{
	display: flex;
  padding: 12px 16px;
  justify-content: center;
  align-items: center;
  gap: 10px;
  border-radius: 4px;
}

.button-primary{
	background-color: #151c35;
  color: #ffffff;
}

.button-secondary: {
	background-color: #979797;
}
